 var img=RasterImageDef.GetImageDictionary(db);foreach(DBDictionaryEntry entry in (DBDictionary)tr.GetObject(img,OpenMode.ForRead)){var d=tr.GetObject(entry.Value,OpenMode.ForWrite) as RasterImageDef;if(d==null)continue;var filename=Path.GetFileName(d.SourceFileName);string full=Path.Combine(dir,"Assets",filename);if(!File.Exists(full))throw new FileNotFoundException(full);try{d.SourceFileName=@".\Assets\"+filename;d.Load();}catch{d.SourceFileName=full;d.Load();}if(!d.IsLoaded)throw new InvalidOperationException("Imagen no cargada: "+filename);logs.Add("IMAGEN CARGADA: "+d.SourceFileName);}
 if(!expected.SequenceEqual(Signature(db,tr)))throw new InvalidOperationException("Geometría modificada al verificar.");logs.Add("Los detalles incorporados conservan sus cotas de origen: queda pendiente compatibilizar interfaces con el perfil.");tr.Commit();}
 doc.Editor.Regen();Plot(db,Path.Combine(dir,"1107.001.00.14-200-14-P-005-CORREGIDO.pdf"));db.SaveAs(Path.Combine(dir,"1107.001.00.14-200-14-P-005-CORREGIDO.dwg"),DwgVersion.Current);File.WriteAllLines(Path.Combine(dir,"VERIFICACION-FINAL.txt"),logs);doc.Editor.WriteMessage("\nP005VERIFYFINAL_DONE\n");}
 [CommandMethod("P005PUBLISH")]
 public void Publish(){var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;if(!doc.Name.Contains("EntregaFinal")||!doc.Name.EndsWith("P-005-CORREGIDO.dwg",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Solo se permite publicar la copia local.");var dir=Path.Combine(Root,"EntregaFinal");var log=new List<string>();using(var tr=db.TransactionManager.StartTransaction()){
 var expected=File.ReadAllLines(Path.Combine(Root,"geometry-before.txt"));if(!expected.SequenceEqual(Signature(db,tr)))throw new InvalidOperationException("Geometría nativa distinta.");var ps=(BlockTableRecord)tr.GetObject(((Layout)tr.GetObject(LayoutManager.Current.GetLayoutId("A"),OpenMode.ForRead)).BlockTableRecordId,OpenMode.ForWrite);var all=ps.Cast<ObjectId>().Select(i=>tr.GetObject(i,OpenMode.ForRead)).OfType<Entity>().ToArray();
 var detail=all.OfType<Viewport>().Single(v=>v.On&&Math.Abs(v.Width-140)<.01);detail.UpgradeOpen();detail.Locked=false;detail.CenterPoint+=new Vector3d(20,0,0);detail.Locked=true;
 foreach(var e in all){if(!e.Visible||e is Viewport||e is Table||e is RasterImage)continue;Extents3d b;try{b=e.GeometricExtents;}catch{continue;}if((b.MinPoint.X>=550&&b.MaxPoint.X<=715&&b.MinPoint.Y>=310&&b.MaxPoint.Y<=412)||(e is MText mt&&(mt.Text.StartsWith("SECCIÓN 12 -")||mt.Text.StartsWith("ESCALA 1:20 - VER"))))Move(e,Matrix3d.Displacement(new Vector3d(20,0,0)));}
 var profile=(Viewport)E(db,tr,"1B266");profile.Locked=false;profile.CenterPoint+=new Vector3d(0,8,0);profile.Locked=true;foreach(var e in all){if(!e.Visible||e is Viewport||e is Table||e is RasterImage)continue;Extents3d b;try{b=e.GeometricExtents;}catch{continue;}if(b.MinPoint.X>=35&&b.MaxPoint.X<=610&&b.MinPoint.Y>=88&&b.MaxPoint.Y<=378)Move(e,Matrix3d.Displacement(new Vector3d(0,8,0)));}
 var styles=(TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForRead);foreach(var mt in all.OfType<MText>().Where(m=>m.Visible&&m.Text.StartsWith("SECCIÓN 12 -"))){mt.UpgradeOpen();mt.TextHeight=3;mt.TextStyleId=styles["REV_CALIBRI"];}
 if(!expected.SequenceEqual(Signature(db,tr)))throw new InvalidOperationException("La geometría Civil cambió.");log.Add("DWG reabierto y verificado. Geometría Civil conservada: eje 84.64245629 m, perfiles y superficies recibidos.");log.Add("Presentación: planta/perfil 1:175 A1, 1:350 A3. Sección original P-012 a 1:20.");log.Add("Sección y perfil separados. Tablas y referencias revisadas. Anotaciones añadidas: CAD editable.");log.Add("34 observaciones gráficas con X; 7 pendientes o parciales detalladas en OBSERVACIONES-MARCADAS.pdf.");tr.Commit();}
 doc.Editor.Regen();Plot(db,Path.Combine(dir,"1107.001.00.14-200-14-P-005-LEVANTAMIENTO.pdf"));db.SaveAs(Path.Combine(dir,"1107.001.00.14-200-14-P-005-LEVANTAMIENTO.dwg"),DwgVersion.Current);File.WriteAllLines(Path.Combine(dir,"VERIFICACION-ENTREGA.txt"),log);doc.Editor.WriteMessage("\nP005PUBLISH_DONE\n");}
